package dev.zomboid.firstaid;
import java.util.*;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.item.ItemStack;import ichttt.mods.firstaid.survival.ClinicalHooks;
public class ArmorChecks{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static void near(double a,double b,String s){ok(Math.abs(a-b)<.0001,s);}
 public enum Zone{HEAD(EquipmentSlot.HEAD),BODY(EquipmentSlot.CHEST),LEFT_ARM(EquipmentSlot.CHEST),RIGHT_ARM(EquipmentSlot.CHEST),LEFT_LEG(EquipmentSlot.LEGS),RIGHT_LEG(EquipmentSlot.LEGS),LEFT_FOOT(EquipmentSlot.FEET),RIGHT_FOOT(EquipmentSlot.FEET);public final EquipmentSlot slot;Zone(EquipmentSlot s){slot=s;}}
 public static class Part{public Zone part;public float health,max;public Part(Zone z){part=z;max=z==Zone.HEAD?16:z==Zone.BODY?30:6;health=max;}public float getMaxHealth(){return max;}}
 public static class Player{public Map<EquipmentSlot,ItemStack>gear=new EnumMap<>(EquipmentSlot.class);public Player(){for(EquipmentSlot s:EquipmentSlot.values())gear.put(s,new ItemStack(0));}public ItemStack getItemBySlot(EquipmentSlot s){return gear.get(s);}}
 public record Source(boolean armorBypass){public boolean is(Object tag){return armorBypass;}}
 static int shots(Zone z,double armor,float raw){Player p=new Player();p.gear.get(z.slot).armor=armor;Part part=new Part(z);int shots=0;while(part.health>0&&shots<1000){part.health-=ArmorTolerance.damage(part,raw,p);shots++;}return shots;}
 public static void main(String[]args){ClinicalHooks.BULLET.set(true);ArmorTolerance.enter(new Source(false));
  for(Zone zone:Zone.values()){float raw=zone==Zone.HEAD?10:5;ok(shots(zone,8,raw)==16,"eight local armor points means sixteen TOTAL reference pistol hits: "+zone);ok(shots(zone,8,raw*4)==4,"fourfold damaging heavy impact consumes protection faster: "+zone);ok(shots(zone,8,raw/2)==32,"half damage at distance requires twice as many hits: "+zone);ok(shots(zone,8,raw*1.5f)==11,"higher damaging ammo needs fewer impacts: "+zone);}
  ok(shots(Zone.HEAD,0,10)==8&&shots(Zone.BODY,0,5)==15,"unarmored nominal head8 torso15 retained");ok(shots(Zone.HEAD,1,10)==8,"weak helmet never worsens unarmored head survival");ok(shots(Zone.HEAD,12,10)==24,"twelve armor points supports twenty four reference hits");
  Player p=new Player();p.gear.get(EquipmentSlot.CHEST).armor=8;Part head=new Part(Zone.HEAD),body=new Part(Zone.BODY);near(ArmorTolerance.damage(head,10,p),2,"chest plate cannot protect head");near(ArmorTolerance.damage(body,5,p),30./16,"chest plate protects torso");near(ArmorTolerance.damage(new Part(Zone.LEFT_ARM),5,p),6./16,"chest plate protects arm through native slot mapping");
  ArmorTolerance.enter(new Source(true));near(ArmorTolerance.damage(head,10,p),2,"armor bypass source ignores local armor");p.gear.get(EquipmentSlot.HEAD).armor=8;near(ArmorTolerance.damage(head,10,p),2,"bypass remains effective with equipped helmet");ArmorTolerance.exit();near(ArmorTolerance.damage(head,10,p),1,"nested source returns to armored hit");
  float apHealth=16;int ap=0;while(apHealth>0){apHealth-=ArmorTolerance.damage(head,5,p);ArmorTolerance.enter(new Source(true));apHealth-=ArmorTolerance.damage(head,5,p);ArmorTolerance.exit();ap++;}ok(ap==11,"native fifty percent AP split handled once without multiplying penetration again");
  Part damaged=new Part(Zone.HEAD);damaged.health=8;int hits=0;while(damaged.health>0){damaged.health-=ArmorTolerance.damage(damaged,10,p);hits++;}ok(hits==8,"wounded part keeps remaining health instead of resetting hit counter");
  Part breaking=new Part(Zone.HEAD);for(int i=0;i<8;i++)breaking.health-=ArmorTolerance.damage(breaking,10,p);p.gear.get(EquipmentSlot.HEAD).armor=0;int after=0;while(breaking.health>0){breaking.health-=ArmorTolerance.damage(breaking,10,p);after++;}ok(after==4,"broken or removed helmet immediately loses protection without healing");
  near(ArmorTolerance.restoreArmorDamage(1,10),10,"bullet uses local formula without second vanilla armor multiplier");near(ArmorTolerance.leftover(.5f,10,1),5,"overflow converted back into raw input units");near(ArmorTolerance.leftover(0,10,1),0,"no artificial overflow when a part survives");
  ClinicalHooks.BULLET.set(false);near(ArmorTolerance.damage(head,4,p),2,"nonbullet critical damage keeps original scaling");near(ArmorTolerance.damage(new Part(Zone.LEFT_LEG),4,p),4,"nonbullet limb damage unchanged");near(ArmorTolerance.restoreArmorDamage(1,10),1,"vanilla armor reduction remains for melee and other damage");near(ArmorTolerance.leftover(.5f,10,1),.5,"nonbullet overflow remains original");ClinicalHooks.BULLET.set(true);
  com.tacz.guns.api.TimelessAPI.missing=true;ok(shots(Zone.HEAD,8,10)==16,"fallback registered pistol reference works without Glock id");com.tacz.guns.api.TimelessAPI.missing=false;
  for(Zone zone:Zone.values())for(int armor=0;armor<=30;armor++)for(int power=1;power<=20;power++){float max=zone==Zone.HEAD?16:zone==Zone.BODY?30:6;float raw=power*.5f;float damage=ArmorTolerance.healthDamage(zone.name(),max,raw,5,2,armor);ok(Float.isFinite(damage)&&damage>0,"finite positive ballistic damage");if(armor>0)ok(damage<=ArmorTolerance.healthDamage(zone.name(),max,raw,5,2,armor-1)+.00001,"more armor never increases damage");ok(ArmorTolerance.healthDamage(zone.name(),max,raw*2,5,2,armor)>damage,"heavier actual projectile cannot hit the hard cap of the previous version");}
  ArmorTolerance.exit();ok(ArmorTolerance.SOURCES.get().isEmpty(),"source context released");ArmorTolerance.exit();System.out.println("ARMOR_CHECKS="+checks);
 }
}
